import sys

def feasible(w, changed):
    # reachable set of last characters
    letters = 'abcdefghijklmnopqrstuvwxyz'
    prev = None
    for i, ch in enumerate(w):
        if i in changed:
            if prev is None:
                cur = set(letters)
            elif len(prev) >= 2:
                cur = set(letters)
            else:
                cur = set(letters) - prev
        else:
            if prev is None or any(p != ch for p in prev):
                cur = {ch}
            else:
                cur = set()
        if not cur:
            return False
        prev = cur
    return True

def solve(w):
    L = len(w)
    best = L
    for mask in range(1 << L):
        k = bin(mask).count('1')
        if k >= best:
            continue
        changed = {i for i in range(L) if mask >> i & 1}
        if feasible(w, changed):
            best = k
    return best

data = sys.stdin.read().split()
n = int(data[0])
print('\n'.join(str(solve(w)) for w in data[1:1 + n]))

